"""Generate a Russian TTS guide for Aura Tachibana ryokan in Hakone-Yumoto."""
import asyncio
import pathlib

import edge_tts
from gtts import gTTS


VOICE = "ru-RU-DmitryNeural"

TEXT = (
    "Добро пожаловать в рёкан Аура Татибана в Хаконэ-Юмото. Рёкан — это не просто гостиница, а традиционный японский формат гостеприимства, где отдых строится вокруг тишины, горячих источников, сезонной кухни и внимательного отношения к деталям. "
    "Аура Татибана расположена на возвышенности над курортным городком Хаконэ-Юмото. Отсюда начинается спокойная часть нашего путешествия после насыщенного дня и дороги из Токио. При входе обратите внимание на японский обычай снимать уличную обувь там, где это указывает персонал. В номере можно переодеться в юкату — лёгкое хлопковое кимоно. Обычно левую полу юкаты запахивают поверх правой и закрепляют поясом. В юкате можно ходить по рёкану, отправляться в онсэн и приходить на ужин. "
    "Главная особенность рёкана — природная термальная вода Хаконэ-Юмото. По данным отеля, это прозрачный слабощелочной источник с показателем пи-аш восемь целых семь десятых. Вода считается мягкой для кожи. В больших общественных купальнях есть внутренние и открытые ванны, а также сауна. Вечером они работают с трёх часов дня до полуночи, а утром — с пяти до половины десятого. "
    "Перед входом в онсэн оставьте обувь и одежду в раздевалке. Купальник в общественной купальне не используют. Сначала тщательно вымойтесь в душевой зоне, сидя на низком стульчике, и только после этого заходите в общую ванну. Маленькое полотенце не опускают в воду: его оставляют у края или кладут на голову. В самом бассейне не плавают и стараются разговаривать тихо. Если у кого-то есть татуировки или медицинские ограничения, лучше заранее уточнить правила у стойки регистрации. После горячей ванны полезно выпить воды и немного отдохнуть. "
    "На верхнем этаже находятся три отдельные открытые купальни с видом на горы Хаконэ. Они называются Ано-ю, Уно-ю и Рано-ю. Это частные купальни, которые бронируются после заселения. Официальная продолжительность сеанса — сорок пять минут, стоимость — три тысячи триста иен. Они расположены примерно на высоте двухсот метров и особенно приятны на закате или вечером, когда над горами появляется звёздное небо. Полотенца туда нужно взять из номера. "
    "Ещё одна важная часть пребывания в рёкане — ужин. Аура Татибана подаёт авторскую японскую кухню, основанную на сезонных продуктах Хаконэ и соседних районов. Отель называет свою концепцию Бэппин-рёри: блюда должны быть красивыми и внешне, и по содержанию. Меню меняется в зависимости от сезона и поставок и может включать закуски, суп, сашими, рыбу или мясо, блюда из местных овощей и десерт. Не спешите: такой ужин задуман как последовательность небольших подач. Если есть аллергии или ограничения, о них необходимо сообщить персоналу заранее. "
    "Ужин обычно начинается в одном из двух временных интервалов: с шести до половины седьмого или с семи до половины восьмого вечера. Уточните назначенное время при заселении, чтобы не опоздать. Утром подают традиционный японский завтрак с местным рисом, овощами, юбой и другими небольшими блюдами. Доступные часы начала завтрака — половина восьмого, восемь или половина девятого. "
    "Сегодня не нужно торопиться. Переоденьтесь в юкату, сходите в онсэн до ужина, спокойно познакомьтесь с японской кухней, а вечером вернитесь к горячему источнику. Именно такой неторопливый ритм помогает почувствовать, чем рёкан отличается от обычного отеля. Приятного отдыха в Аура Татибана."
)


async def main():
    out_dir = pathlib.Path("mp3")
    out_dir.mkdir(exist_ok=True)
    out_path = out_dir / "Aura Tachibana.mp3"
    try:
        communication = edge_tts.Communicate(TEXT.strip(), VOICE)
        await communication.save(str(out_path))
    except Exception as error:
        print(f"Edge TTS unavailable ({error}); using gTTS fallback")
        gTTS(TEXT.strip(), lang="ru").save(str(out_path))
    print(f"Saved: {out_path} ({out_path.stat().st_size / 1024:.0f} KB)")


asyncio.run(main())